/// <summary>
/// Data contract for vendor claim journal process
/// </summary>
[DataContract]
internal final class METVendClaimJournalContract implements SysOperationValidatable
{
    NoYesId   processStandardCostClaim;
    NoYesId   processExciseDutyClaim;
    NoYesId   processDutyVarianceClaim;
    NoYesId   postClaim;

    str       packedQuery;


}

Method.Source:
/// <summary>
/// Contract member indicates whether to process standard cost claims
/// </summary>
/// <param name = "_processStandardCostClaim">Standard cost claim parameter</param>
/// <returns>Standard cost claim parameter</returns>
[DataMemberAttribute, SysOperationLabelAttribute("@MET:StandardCostClaimProcess")]
public NoYesId parmProcessStandardCostClaim(NoYesId _processStandardCostClaim = processStandardCostClaim)
{
    processStandardCostClaim = _processStandardCostClaim;
    return processStandardCostClaim;
}

/// <summary>
/// Contract member indicates whether to process Excise duty free item claims
/// </summary>
/// <param name = "_processExciseDutyClaim">Excise duty free item claim parameter</param>
/// <returns>>Excise duty free item claim parameter</returns>
[DataMemberAttribute, SysOperationLabelAttribute("@MET:ExciseFreeItemClaimProcess")]
public NoYesId parmProcessExciseDutyClaim(NoYesId _processExciseDutyClaim = processExciseDutyClaim)
{
    processExciseDutyClaim = _processExciseDutyClaim;
    return processExciseDutyClaim;
}

/// <summary>
/// Contract member indicates whether to process Excise duty variance claims
/// </summary>
/// <param name = "_processDutyVarianceClaim">Excise duty variance claim parameter</param>
/// <returns>Excise duty variance claim parameter</returns>
[DataMemberAttribute, SysOperationLabelAttribute("@MET:DutyVarianceClaimProcess")]
public NoYesId parmProcessDutyVarianceClaim(NoYesId _processDutyVarianceClaim = processDutyVarianceClaim)
{
    processDutyVarianceClaim = _processDutyVarianceClaim;
    return processDutyVarianceClaim;
}

/// <summary>
/// Indicates whether to post the claim journals after creation
/// </summary>
/// <param name = "_postClaim">Post claims</param>
/// <returns>Post claims</returns>
[DataMemberAttribute, SysOperationLabelAttribute("@SYS86511")]
public NoYesId parmPostClaim(NoYesId _postClaim = postClaim)
{
    postClaim = _postClaim;
    return postClaim;
}

/// <summary>
/// initialise and return query
/// </summary>
/// <param name = "_packedQuery">Site query</param>
/// <returns>Site query</returns>
[DataMemberAttribute, AifQueryTypeAttribute(identifierStr(_packedQuery), queryStr(InventSitesSRS))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Gets the query from packed query
/// </summary>
/// <returns>Query instance</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Sets the packed query from Query instance
/// </summary>
/// <param name = "_query">Query instance</param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}

    /// <summary>
    /// Validates the input parameters
    /// </summary>
    /// <returns>True if parameters are valid. otherwise false</returns>
    public boolean validate()
    {
        boolean isValid = true;

        if(!(processStandardCostClaim || processDutyVarianceClaim || processExciseDutyClaim))
        {
            isValid = checkFailed("@MET:VendorClaimProcessContractValidationMsg");
        }
        return isValid;
    }
